<h1><?= e($pageTitle ?? 'Appointments') ?></h1><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Date</th><th>Time</th><th>Patient</th><th>Doctor</th><th>Status</th><th>Reason</th><th>Action</th></tr></thead><tbody><?php foreach ($appointments as $a): ?><tr><td><?= e($a['appointment_date']) ?></td><td><?= e($a['appointment_time']) ?></td><td><?= e($a['patient_name'] ?? '') ?></td><td><?= e($a['doctor_name'] ?? '') ?></td><td><span class="badge bg-secondary"><?= e($a['status']) ?></span></td><td><?= e($a['reason']) ?></td><td><form method="post" class="d-flex gap-2"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><select name="status" class="form-select form-select-sm"><option>Pending</option><option>Approved</option><option>Completed</option><option>Cancelled</option><option>Missed</option></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div>
